import { DarkTheme, DefaultTheme, Stack, ThemeProvider } from 'expo-router';
import { useColorScheme } from 'react-native';

/**
 * The root navigator. A plain Stack until the app shell lands: the tab bar, header and the
 * app's own theme tokens come with it, generated by the same palette script as the web's
 * globals.css. Until then the router's stock light and dark themes follow the system, so the
 * placeholder is never a white screen in dark mode and no colour is hard-coded.
 */
export default function RootLayout() {
  const scheme = useColorScheme();
  return (
    <ThemeProvider value={scheme === 'dark' ? DarkTheme : DefaultTheme}>
      <Stack screenOptions={{ headerShown: false }} />
    </ThemeProvider>
  );
}
